using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class GangAssaultTests
    {
        static readonly Action<GangState> Save=s=>{};
        static GangTurfAttempt Attempt()
        {
            var areas=GangTurfOptions.Defaults().Areas;var c=GangAssaultOptions.Defaults();
            return new GangTurfAttempt{Id="convoy",Gang="Mine",PreviousOwner="Enemy",Mode=GangTurfMode.Attack,Area=areas[1],Radius=45,SecondsLimit=600,Models=Enumerable.Repeat("g_m_y_famca_01",6).ToArray(),InitialDefenders=3,Assault=new GangAssaultPlan{Origin=areas[0],Options=c,Bay=CharacterRules.Copy(c.Origins[0]),CrewModels=Enumerable.Repeat("g_m_y_famca_01",15).ToArray()}};
        }
        static GangState State()=>new GangState{Gang="Mine",Reputation=123,Rank=1,TerritoriesEnabled=true,Turf=new GangTurfData{Owners={{1,"Mine"},{2,"Enemy"}}}};
        static GangState Begin(){Assert.True(GangTurfTransactions.Begin(State(),Attempt(),Save,out var s));return s;}
        static GangSpot Target(GangState s)=>CharacterRules.Copy(s.Turf.Pending.Area.Center);
        static GangState Arrived(){var s=Begin();Assert.True(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out s));return s;}
        static GangState Ready(){var s=Arrived();for(int i=0;i<6;i++)Assert.True(GangTurfTransactions.Defeat(s,"convoy",i,Save,out s));return s;}
        [Fact] public void FifteenOriginsHaveSixtySourcePositionsAndHeadings(){var c=GangAssaultOptions.Defaults();Assert.True(c.Valid);Assert.Equal(15,c.Origins.Count);Assert.Equal(60,c.Origins.Sum(o=>o.Spawns.Count));Assert.Equal("granger",c.VehicleModel);Assert.Equal(600,c.TravelSeconds);Assert.Equal(65,c.ArrivalRadius);Assert.Equal(100,c.EscortRadius);Assert.Equal(1312.486f,c.Origins[0].Spawns[0].X);Assert.Equal(34.87109f,c.Origins[0].Spawns[0].Heading);}
        [Fact] public void ExistingCaptureHasNoAssaultOrNewTravelRequirements(){var p=Attempt();var j=JObject.FromObject(p);j.Remove("Assault");var old=j.ToObject<GangTurfAttempt>();Assert.Null(old.Assault);Assert.True(old.Valid);var s=State();Assert.True(GangTurfTransactions.Begin(s,old,Save,out s));Assert.True(GangTurfTransactions.Defeat(s,"convoy",0,Save,out s));}
        [Fact] public void BeginningSavesDeepPlanWithoutMoneyOrOwnerChanges(){var p=Attempt();var s=State();int saves=0;Assert.True(GangTurfTransactions.Begin(s,p,n=>saves++,out var n));Assert.Equal(1,saves);p.Assault.Bay.Spawns[0].X=0;p.Assault.Options.TravelSeconds=120;p.Assault.CrewModels[0]="changed";Assert.NotEqual(0,n.Turf.Pending.Assault.Bay.Spawns[0].X);Assert.Equal(600,n.Turf.Pending.Assault.Options.TravelSeconds);Assert.Equal("g_m_y_famca_01",n.Turf.Pending.Assault.CrewModels[0]);Assert.Null(s.Turf.Pending);Assert.Equal("Enemy",n.Turf.Owners[2]);Assert.Equal(123,n.Reputation);Assert.Equal(1,n.Turf.Attempts);}
        [Fact] public void CannotLaunchFromForeignOriginOrAttackOwnTarget(){var s=State();s.Turf.Owners[1]="Other";Assert.False(GangTurfTransactions.Begin(s,Attempt(),Save,out _));s=State();s.Turf.Owners[2]="Mine";Assert.False(GangTurfTransactions.Begin(s,Attempt(),Save,out _));}
        [Fact] public void LaunchRejectsPreCompletedTravelAndHiddenCasualties(){var p=Attempt();p.Assault.Progress.Arrived=true;Assert.False(GangTurfTransactions.Begin(State(),p,Save,out _));p=Attempt();p.Assault.Progress.TravelElapsed=1000;Assert.False(GangTurfTransactions.Begin(State(),p,Save,out _));p=Attempt();p.Assault.Progress.LostCrew.Add(1);Assert.False(GangTurfTransactions.Begin(State(),p,Save,out _));}
        [Fact] public void CannotScoreDefenderKillsOrRestartBattleBeforePhysicalArrival(){var s=Begin();Assert.False(GangTurfTransactions.Defeat(s,"convoy",0,Save,out _));Assert.False(GangTurfTransactions.Restart(s,"convoy",Save,out _));Assert.False(GangTurfTransactions.Capture(s,"convoy",Save,out _));Assert.Empty(s.Turf.Pending.Defeated);}
        [Fact] public void ArrivalNeedsLeadDriverAndLivingEscortNearby(){var s=Begin();Assert.False(GangAssaultTransactions.Arrive(s,"convoy",false,Target(s),0,true,Save,out _));Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,false,Save,out _));Assert.False(s.Turf.Pending.Assault.Progress.Arrived);Assert.True(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out s));Assert.True(s.Turf.Pending.Assault.Progress.Arrived);Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));}
        [Fact] public void ArrivalRejectsWrongFloorDistanceSpeedAndDestroyedLead(){var s=Begin();var target=Target(s);target.Z+=9;Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,target,0,true,Save,out _));target=Target(s);target.X+=66;Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,target,0,true,Save,out _));Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),1.5f,true,Save,out _));Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),float.NaN,true,Save,out _));s.Turf.Pending.Assault.Progress.LostCars.Add(0);Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));}
        [Fact] public void LostEscortDriversCannotBeInventedByArrivalCallback(){var s=Begin();var p=new GangAssaultProgress{LostCrew={3,7,11}};Assert.True(GangAssaultTransactions.Sample(s,"convoy",p,Save,out s));Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));}
        [Fact] public void ExpiredTravelCannotBeMarkedAsSuccessfulArrival(){var s=Begin();var p=new GangAssaultProgress{TravelElapsed=600000};Assert.True(GangAssaultTransactions.Sample(s,"convoy",p,Save,out s));Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));}
        [Fact] public void TravelAndBattleTimePersistAcrossIndependentStages(){var s=Begin();Assert.True(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{TravelElapsed=234000},Save,out s));Assert.True(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out s));Assert.True(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{Arrived=true,TravelElapsed=234000,BattleElapsed=42000},Save,out s));s=CharacterRules.Copy(s);Assert.Equal(234000,s.Turf.Pending.Assault.Progress.TravelElapsed);Assert.Equal(42000,s.Turf.Pending.Assault.Progress.BattleElapsed);Assert.True(s.Turf.Pending.Assault.Progress.Arrived);}
        [Fact] public void CheckpointCannotTeleportToBattleOrResetTime(){var s=Begin();Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{Arrived=true},Save,out _));Assert.True(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{TravelElapsed=1000},Save,out s));Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{TravelElapsed=999},Save,out _));Assert.True(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out s));Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{Arrived=false,TravelElapsed=1000},Save,out _));Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{Arrived=true,TravelElapsed=1001},Save,out _));}
        [Fact] public void ConfirmedCasualtiesAndWrecksCannotBeRestoredByReload(){var s=Begin();var p=new GangAssaultProgress{TravelElapsed=5000,LostCrew={0,3},LostCars={1}};Assert.True(GangAssaultTransactions.Sample(s,"convoy",p,Save,out s));s=CharacterRules.Copy(s);Assert.Equal(new[]{0,3},s.Turf.Pending.Assault.Progress.LostCrew);Assert.Equal(new[]{1},s.Turf.Pending.Assault.Progress.LostCars);p.LostCrew.Clear();Assert.False(GangAssaultTransactions.Sample(s,"convoy",p,Save,out _));}
        [Fact] public void CarWreckDoesNotRequireAllPassengersToBeDeclaredDead(){var s=Begin();var p=new GangAssaultProgress{LostCars={1}};Assert.True(GangAssaultTransactions.Sample(s,"convoy",p,Save,out s));Assert.Empty(s.Turf.Pending.Assault.Progress.LostCrew);Assert.False(GangAssaultRules.NoEscort(s.Turf.Pending.Assault.Progress));}
        [Fact] public void ArrivalAndBattleSamplesRejectChangedTargetOwnerAndGang(){var s=Begin();s.Gang="Other";Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress(),Save,out _));s=Begin();s.Turf.Owners[2]="External";Assert.False(GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out _));Assert.Equal("External",s.Turf.Owners[2]);}
        [Fact] public void FailedBeginArrivalSampleAndCompletionSaveKeepOriginalByteIdentical(){var s=State();string before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangTurfTransactions.Begin(s,Attempt(),n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));s=Begin();before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,n=>throw new Exception(),out _));Assert.Throws<Exception>(()=>GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{TravelElapsed=1000},n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));s=Ready();before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangTurfTransactions.Capture(s,"convoy",n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));}
        [Fact] public void ReinforcementsAndAllDefendersAreRequiredBeforeCapture(){var s=Arrived();for(int i=0;i<3;i++)GangTurfTransactions.Defeat(s,"convoy",i,Save,out s);Assert.False(s.Turf.Pending.Ready);Assert.False(GangTurfTransactions.Capture(s,"convoy",Save,out _));for(int i=3;i<6;i++)GangTurfTransactions.Defeat(s,"convoy",i,Save,out s);Assert.True(s.Turf.Pending.Ready);Assert.True(GangTurfTransactions.Capture(s,"convoy",Save,out s));Assert.Equal("Mine",s.Turf.Owners[2]);Assert.Equal(173,s.Reputation);Assert.Equal(1,s.Turf.Captures);}
        [Fact] public void ReadyCaptureReloadDoesNotNeedConvoyOrAnotherBattle(){var s=CharacterRules.Copy(Ready());Assert.True(s.Turf.Pending.Ready);Assert.True(GangTurfTransactions.Capture(s,"convoy",Save,out s));Assert.Null(s.Turf.Pending);Assert.True(GangTurfTransactions.Capture(s,"convoy",n=>throw new Exception(),out s));Assert.Equal(1,s.Turf.Captures);Assert.Equal(173,s.Reputation);}
        [Fact] public void PartialBattleRestartKeepsArrivalTimeAndCasualties(){var s=Arrived();var p=new GangAssaultProgress{Arrived=true,BattleElapsed=10000,LostCrew={2,7}};GangAssaultTransactions.Sample(s,"convoy",p,Save,out s);GangTurfTransactions.Defeat(s,"convoy",0,Save,out s);Assert.True(GangTurfTransactions.Restart(s,"convoy",Save,out s));Assert.Empty(s.Turf.Pending.Defeated);Assert.Equal(10000,s.Turf.Pending.Assault.Progress.BattleElapsed);Assert.Equal(new[]{2,7},s.Turf.Pending.Assault.Progress.LostCrew);Assert.True(s.Turf.Pending.Assault.Progress.Arrived);Assert.Equal(1,s.Turf.Attempts);}
        [Theory][InlineData(false)][InlineData(true)]public void CancellationOrFailedAssaultNeverTransfersTargetOrTakesMoney(bool failed){var s=Arrived();Assert.True(GangTurfTransactions.End(s,"convoy",failed,Save,out s));Assert.Equal("Enemy",s.Turf.Owners[2]);Assert.Equal("Mine",s.Turf.Owners[1]);Assert.Equal(123,s.Reputation);Assert.Equal(0,s.Turf.LostDefenses);Assert.Equal(0,s.Turf.Captures);Assert.Null(s.Turf.Pending);}
        [Fact] public void AlertSimulationAndNewInitiationsStopWhileAssaultPending(){var s=Begin();Assert.False(GangWarRules.Free(s));s.Warfare=new GangWarData{AttacksEnabled=true,RivalsEnabled=true};Assert.False(GangWarTransactions.Alert(s,new GangWarAlert{Id="alert",Gang="Mine",Attacker="Enemy",Area=s.Turf.Pending.Assault.Origin},Save,out _));Assert.False(GangWarTransactions.Rival(s,s.Turf.Pending.Area,"A","Enemy",true,"battle",Save,out _));s.Gang=null;Assert.False(GangLoyaltyTransactions.Begin(s,new GangLoyaltyAttempt{Id="loyal",Gang="Mine",Leader=new GangSpot(),Contacts=GangLoyaltyOptions.Defaults().Contacts.Take(2).ToList()},Save,out _));}
        [Fact] public void UnknownFieldsSurviveArrivalAndCompletion(){var j=JObject.FromObject(Begin());j["FutureRoot"]=42;j["Turf"]["FutureBook"]="keep";j["Turf"]["Pending"]["Assault"]["FuturePlan"]="keep";j["Turf"]["Pending"]["Assault"]["Progress"]["FutureProgress"]=7;var s=j.ToObject<GangState>();GangAssaultTransactions.Arrive(s,"convoy",true,Target(s),0,true,Save,out s);j=JObject.FromObject(s);Assert.Equal("keep",(string)j["Turf"]["Pending"]["Assault"]["FuturePlan"]);Assert.Equal(7,(int)j["Turf"]["Pending"]["Assault"]["Progress"]["FutureProgress"]);for(int i=0;i<6;i++)GangTurfTransactions.Defeat(s,"convoy",i,Save,out s);GangTurfTransactions.Capture(s,"convoy",Save,out s);j=JObject.FromObject(s);Assert.Equal(42,(int)j["FutureRoot"]);Assert.Equal("keep",(string)j["Turf"]["FutureBook"]);}
        [Fact] public void StageSamplesCannotExceedCapturedLimits(){var s=Begin();Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{TravelElapsed=600001},Save,out _));s=Arrived();Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress{Arrived=true,BattleElapsed=600001},Save,out _));}
        [Fact] public void InvalidPlansStayProtectedInsteadOfReplacingProgress(){var s=Begin();s.Turf.Pending.Assault.CrewModels[0]="invalid/model";Assert.False(s.Turf.Valid);Assert.False(GangAssaultTransactions.Sample(s,"convoy",new GangAssaultProgress(),Save,out _));Assert.False(GangTurfTransactions.End(s,"convoy",false,Save,out _));}
        [Fact] public void ProgressRejectsDuplicateOrOutOfRangeCasualties(){Assert.False(new GangAssaultProgress{LostCrew={1,1}}.Valid);Assert.False(new GangAssaultProgress{LostCrew={15}}.Valid);Assert.False(new GangAssaultProgress{LostCars={4}}.Valid);Assert.False(new GangAssaultProgress{TravelElapsed=-1}.Valid);Assert.False(new GangAssaultProgress{BattleElapsed=1}.Valid);}
        [Theory][InlineData(0,0,0)][InlineData(1,0,1)][InlineData(2,0,2)][InlineData(3,1,-1)][InlineData(4,1,0)][InlineData(6,1,2)][InlineData(7,2,-1)][InlineData(10,2,2)][InlineData(11,3,-1)][InlineData(14,3,2)][InlineData(15,-1,-99)]public void CrewMappingReservesLeadDriverAndExactlyFifteenSeats(int crew,int car,int seat){Assert.Equal(car,GangAssaultRules.Car(crew));Assert.Equal(seat,GangAssaultRules.Seat(crew));}
        [Fact] public void OnlyLosingAllThreeEscortDriversOrCarsEndsEscortCapability(){var p=new GangAssaultProgress{LostCrew={3,7}};Assert.False(GangAssaultRules.NoEscort(p));p.LostCars.Add(3);Assert.True(GangAssaultRules.NoEscort(p));Assert.False(GangAssaultRules.Driver(0));Assert.True(GangAssaultRules.Driver(11));}
        [Fact] public void ConfigurationRejectsInvalidModelOriginsAndLimits(){var c=GangAssaultOptions.Defaults();c.VehicleModel="bad/model";Assert.False(c.Valid);c=GangAssaultOptions.Defaults();c.Origins.Add(c.Origins[0]);Assert.False(c.Valid);c=GangAssaultOptions.Defaults();c.Origins[0].Spawns.RemoveAt(0);Assert.False(c.Valid);c=GangAssaultOptions.Defaults();c.TravelSeconds=0;Assert.False(c.Valid);c=GangAssaultOptions.Defaults();c.ArrivalRadius=200;Assert.False(c.Valid);}
        [Fact] public void AssaultCannotMasqueradeAsDefenseOrUseSameOriginAndTarget(){var p=Attempt();p.Area=p.Assault.Origin;Assert.False(p.Valid);p=Attempt();p.Mode=GangTurfMode.Defense;Assert.False(p.Valid);p=Attempt();p.WarAlertId="alert";Assert.False(p.Valid);}
    }
}
